func (fd *File) resolveServices() {
	for i := range fd.L2.Services.List {
		svc := &fd.L2.Services.List[i]
		meths := svc.Methods.List
		for j := range meths {
			meth := &meths[j]
			meth.Input = fd.resolveMessageDependency(fd, meth.L1.InputNameIndex)
			meth.Output = fd.resolveMessageDependency(fd, meth.L1.OutputNameIndex)
		}
	}
}

